add_action( 'enqueue_block_editor_assets', 'perfectpixel_disable_fullscreen_editor' );

function perfectpixel_disable_fullscreen_editor() {
	$js = "wp.domReady( function () {
		var prefs = wp.data.select( 'core/preferences' );
		if ( prefs && prefs.get ) {
			if ( prefs.get( 'core/edit-post', 'fullscreenMode' ) ) {
				wp.data.dispatch( 'core/preferences' ).set( 'core/edit-post', 'fullscreenMode', false );
			}
			return;
		}
		var editPost = wp.data.select( 'core/edit-post' );
		if ( editPost && editPost.isFeatureActive( 'fullscreenMode' ) ) {
			wp.data.dispatch( 'core/edit-post' ).toggleFeature( 'fullscreenMode' );
		}
	} );";
	wp_add_inline_script( 'wp-blocks', $js );
}
